import{z as l,x as i,o as B,c as F,q as o,j as t,D as e,d as A,s,S as n,b as a}from"./chunks/framework.C8m1ZpeB.js";const m=JSON.parse('{"title":"后量子概览","description":"","frontmatter":{"title":"后量子概览","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ce-postquantum-overview.md","filePath":"cs/ce-postquantum-overview.md","lastUpdated":1791063341000}'),S={name:"cs/ce-postquantum-overview.md"};function D(d,E,C,p,c,h){const r=i("Mermaid");return B(),F("div",null,[E[2]||(E[2]=o('<h1 id="后量子概览" tabindex="-1">后量子概览 <a class="header-anchor" href="#后量子概览" aria-label="Permalink to &quot;后量子概览&quot;">​</a></h1><div class="epigraph"><p>量子计算机不改变对称密码的账，它换掉的是公钥那半张表：Shor 把因式分解与离散对数收进多项式时间，整条公钥地基要重铺。</p><footer>—— 据 Shor, 1997；Grover, 1996；NIST FIPS 203/204/205 整理</footer></div><p><a href="/cs/ce-randomness">上一课</a>把原料层钉在熵与 DRBG 上。现在抬头看前沿：本课程至此的全部公钥合同——X25519 协商、ECDSA/EdDSA 签名、RSA 的遗留形状——都站在「大整数分解与椭圆曲线离散对数不可解」这块地基上，而 Shor 算法在足够规模的量子计算机上把两者都收进多项式时间。缺口是<strong>迁移账</strong>：什么先破、什么不用慌、替手的方案是什么族、协议层怎么混合过渡。本课是概览，收下边界，不进格密码的数学。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>威胁按算法分账。Shor 1997：周期查找把因式分解与离散对数归约到量子傅里叶变换，RSA、DH、ECDH、ECDSA 全部在打击面上——公钥侧的整张表。Grover 1996：对对称原语给出平方加速，AES-128 的暴力成本从 \\(2^{128}\\) 落到 \\(2^{64}\\) 量级，翻倍密钥（AES-256）即对冲；哈希的原像同理，抗碰撞的生日界只降常数倍。<span class="marginnote">「平方加速」翻译过来就是：暴力搜索的工作量从 \\(2^n\\) 降到约 \\(2^{n/2}\\)。代入数字看，AES-128 的 \\(2^{128}\\) 次尝试变成 \\(2^{64}\\) 次——听着仍巨大，但已落入国家级对手可规划的射程；而把密钥翻倍到 AES-256，成本回到 \\(2^{128}\\)，裕量又够了。这就是「对称侧不用慌、密钥翻倍即对冲」的来由。</span>这条分账决定了迁移顺序：<strong>机密性先行</strong>——「现在截获、将来解密」（harvest now, decrypt later）只需要对手存密文等机器；签名可以等到量子计算机真的可用再换，因为伪造必须当场完成。Mosca 的不等式把这写成判据：数据保密期加迁移期 \\gt 量子机到货期，就必须现在动 KEM。</p><h3 id="方案族" tabindex="-1">方案族 <a class="header-anchor" href="#方案族" aria-label="Permalink to &quot;方案族&quot;">​</a></h3><p>NIST 2024 年定稿三份标准，覆盖两大族：格上的 ML-KEM（FIPS 203，原 Kyber，接替 ECDH 的位置）与 ML-DSA（FIPS 204，原 Dilithium，接替签名位置）；哈希签名的 SLH-DSA（FIPS 205，原 SPHINCS+，保守但尺寸大）。之外编码族的 Classic McEliece（密钥巨大、更保守）留在备用位。谱系里也有反面教材：同属决赛圈的同源（isogeny）方案 SIKE，2022 年被经典（非量子）攻击在单核约一小时内击穿——「新结构」不等于「更安全」，标准化过程的意义正是让方案被公开拷打几年。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>迁移口径四条。其一，协商用混合：X25519 与 ML-KEM-768 各封装一次，两个共享秘密拼接过 KDF——上一课 <a href="/cs/ce-kem-hybrid">KEM 与混合加密</a>的合同原样适用；任一被破另一边还撑着，代价是握手多约 2 KB。其二，签名分阶段：先在支持双签的场合并存（经典与 ML-DSA），证书链与代码签名这类「验证设备寿命长」的场合最先动，固件里的验证器一用十年。其三，按 Mosca 判据排期：长保密期数据（医疗档案、国家档案）的加密迁移第一优先。<span class="marginnote">「现在截获、将来解密」可以类比成：有人今天拍下你寄出的每张明信片，等几十年后某种读信机器问世，再逐张把内容读出来。明信片一旦寄出就收不回，数据一旦被截走就追不回——所以防御必须赶在「寄出」（加密）那一刻之前完成，这正是机密性先行的时间逻辑。</span>其四，对称层不动：AES-256 与 SHA-384 在 Grover 界下余量充足，AEAD 结构、nonce 纪律、本课程前七课的对称合同原样保留——后量子换的是公钥侧，不是重学一遍。</p>',9)),(B(),t(n,null,{default:e(()=>[s(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E9%87%8F%E5%AD%90%E5%A8%81%E8%83%81%22%5D%20--%3E%20SHOR%5B%22Shor%EF%BC%9A%E5%85%AC%E9%92%A5%E5%9C%B0%E5%9F%BA%E5%A1%8C%22%5D%0A%20%20Q%20--%3E%20GROVER%5B%22Grover%EF%BC%9A%E5%AF%B9%E7%A7%B0%E5%B9%B3%E6%96%B9%E5%8A%A0%E9%80%9F%EF%BC%8C%E7%BF%BB%E5%80%8D%E5%AF%86%E9%92%A5%E5%AF%B9%E5%86%B2%22%5D%0A%20%20SHOR%20--%3E%20MIG%5B%22%E8%BF%81%E7%A7%BB%E9%A1%BA%E5%BA%8F%EF%BC%9A%E6%9C%BA%E5%AF%86%E6%80%A7%E5%85%88%E8%A1%8C%22%5D%0A%20%20MIG%20--%3E%20KEM%5B%22KEM%EF%BC%9AX25519%20%2B%20ML-KEM%20%E6%B7%B7%E5%90%88%E5%B0%81%E8%A3%85%22%5D%0A%20%20MIG%20--%3E%20SIG%5B%22%E7%AD%BE%E5%90%8D%EF%BC%9A%E7%BB%8F%E5%85%B8%E4%B8%8E%20ML-DSA%20%E5%B9%B6%E5%AD%98%E8%BF%87%E6%B8%A1%22%5D%0A%20%20KEM%20--%3E%20HKDF%5B%22%E6%8B%BC%E6%8E%A5%E5%85%B1%E4%BA%AB%E7%A7%98%E5%AF%86%E8%BF%87%20KDF%22%5D%0A%20%20SIG%20--%3E%20LONG%5B%22%E9%95%BF%E5%AF%BF%E5%91%BD%E9%AA%8C%E8%AF%81%E8%AE%BE%E5%A4%87%E6%9C%80%E5%85%88%E5%8A%A8%22%5D%0A%20%20GROVER%20--%3E%20KEEP%5B%22%E5%AF%B9%E7%A7%B0%E5%90%88%E5%90%8C%E4%B8%8D%E5%8F%98%EF%BC%9AAEAD%20%2F%20nonce%20%2F%20%E7%86%B5%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[A(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[A("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,[A("「机密性先行」的机制根据是"),a("strong",null,"攻击的时间方向"),A("。解密攻击可以在密文产生多年后执行——对手的唯一成本是存储，因此防御必须赶在加密那一刻完成；伪造签名却必须在被验证的那一刻完成，量子机到货前不存在「先存着」的签名攻击，所以签名迁移可以等标准化与硬件生态成熟再收口。混合封装为什么不是「双倍强度」而是「取较弱侧」：攻击者只需攻破拼接中任意一份就能推进——混合防的是「单一方案被整体击穿」，不防「两侧方案同一天各破一半」。SIKE 之死给出的教训也是机制性的：同源映射的困难性没有多年公开分析支撑，决赛资格不构成安全证据；ML-KEM 与 ML-DSA 站的是被拷打了十几年的格假设（LWE 一族）。")],-1)),E[5]||(E[5]=a("p",null,[a("span",{class:"marginnote"},"尺寸的账：Ed25519 公钥 32 字节、签名 64 字节；ML-DSA-44 公钥 1312 字节、签名 2420 字节。TLS 握手每个方向多约 2 KB、证书多约 1 KB——迁移的真实代价是带宽与解析，不是算法速度。")],-1)),(B(),t(n,null,{default:e(()=>[s(r,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q1%5B%22%E8%BF%99%E4%BB%BD%E6%95%B0%E6%8D%AE%E8%A6%81%E4%BF%9D%E5%AF%86%E5%A4%9A%E5%B0%91%E5%B9%B4%EF%BC%9F%22%5D%20--%3E%20CMP%7B%22%E4%BF%9D%E5%AF%86%E6%9C%9F%E5%8A%A0%E8%BF%81%E7%A7%BB%E6%9C%9F%E5%A4%A7%E4%BA%8E%E9%87%8F%E5%AD%90%E6%9C%BA%E5%88%B0%E8%B4%A7%E6%9C%9F%E5%90%97%EF%BC%9F%22%7D%0A%20%20Q2%5B%22%E6%88%91%E7%9A%84%E8%BF%81%E7%A7%BB%E5%B7%A5%E7%A8%8B%E8%A6%81%E5%A4%9A%E5%B0%91%E5%B9%B4%EF%BC%9F%22%5D%20--%3E%20CMP%0A%20%20Q3%5B%22%E5%A4%A7%E8%A7%84%E6%A8%A1%E9%87%8F%E5%AD%90%E6%9C%BA%E9%A2%84%E8%AE%A1%E5%87%A0%E5%B9%B4%E5%88%B0%E8%B4%A7%EF%BC%9F%22%5D%20--%3E%20CMP%0A%20%20CMP%20--%3E%7C%22%E8%B6%85%E5%87%BA%EF%BC%8C%E6%9D%A5%E4%B8%8D%E5%8F%8A%22%7C%20NOW%5B%22%E7%8E%B0%E5%9C%A8%E5%B0%B1%E5%BE%97%E5%8A%A8%20KEM%EF%BC%9A%E6%B7%B7%E5%90%88%E5%B0%81%E8%A3%85%22%5D%0A%20%20CMP%20--%3E%7C%22%E5%B0%9A%E6%9C%89%E8%A3%95%E9%87%8F%22%7C%20PLAN%5B%22%E6%8C%89%E5%B8%B8%E8%A7%84%E5%8D%87%E7%BA%A7%E5%91%A8%E6%9C%9F%E6%8E%92%E6%9C%9F%22%5D%0A%20%20NOW%20--%3E%20PRIO%5B%22%E9%95%BF%E4%BF%9D%E5%AF%86%E6%9C%9F%E6%95%B0%E6%8D%AE%E6%8E%92%E6%9C%80%E5%89%8D%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[A(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=o('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不进格密码数学（LWE、模格的困难性归约）与量子算法推导；PIR、MPC 这类密码学前沿（见 <a href="/cs/pir">PIR</a>）与本课不在同一条线上。状态化哈希签名（XMSS/LMS）的有状态风险——签名状态一旦重放即灾难——只点名，落进 IoT 与固件场景时按 NIST SP 800-208 口径执行。<span class="marginnote">常见误区：把哈希签名当成「最保守就最安全」的默认选择。XMSS/LMS 的私钥状态必须按严格顺序用、每格只能签一次——设备一旦被刷回旧快照（状态回滚），同一格签两次就可能泄露私钥。管不好状态的场景，宁可换更大但无状态的 SLH-DSA。</span>本课程至此不更换前七课的任何对称侧合同；下一课收束全课程。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Shor 收走全部经典公钥原语；Grover 只给对称平方加速，翻倍密钥即对冲。</li><li>迁移按攻击时间方向排序：机密性先行（harvest now, decrypt later），签名可后动。</li><li>方案族：格（ML-KEM/ML-DSA）、哈希（SLH-DSA）；SIKE 之死说明新结构需要公开拷打。</li><li>混合封装取较弱侧安全性，防单点击穿；对称侧合同原样保留。</li><li>出处：Shor, 1997；Grover, 1996；NIST FIPS 203/204/205；Mosca, 2018。</li></ul>',4))])}const u=l(S,[["render",D]]);export{m as __pageData,u as default};
